import gzip, os, pandas as pd, collections
lib=pd.read_csv('/task/input/library.tsv',sep='\t',dtype=str)
seq=[s.upper() for s in lib.sequence]
rc=lambda s:s.translate(str.maketrans('ACGTN','TGCAN'))[::-1]
idx={s:i for i,s in enumerate(seq)}; ridx={rc(s):i for i,s in enumerate(seq)}
files=sorted(os.listdir('/task/input/fastq'),key=lambda x:int(x[3:-9]))
for fn in files:
    total=multi=0; examples=[]
    with gzip.open('/task/input/fastq/'+fn,'rt') as f:
        for k,line in enumerate(f):
            if k%4!=1: continue
            total+=1; r=line.rstrip(); matches=set()
            for dic in (idx,ridx):
                for p in range(56):
                    i=dic.get(r[p:p+20])
                    if i is not None: matches.add(i)
            if len(matches)>1:
                multi+=1
                if len(examples)<5: examples.append([(lib.sgRNA[i],p) for p in range(56) for i in [idx.get(r[p:p+20])] if i is not None]+[(lib.sgRNA[i],p,'rev') for p in range(56) for i in [ridx.get(r[p:p+20])] if i is not None])
    print(fn,'total',total,'reads_matching_multiple_guides',multi,'examples',examples)
