import pandas as pd, numpy as np
C=pd.read_csv('/tmp/counts_allpos.tsv',sep='\t',index_col=0)
lib=pd.read_csv('/task/input/library.tsv',sep='\t').set_index('sgRNA'); C=C.loc[lib.index]
nt=lib.gene.eq('NON_TARGETING').values
groups={'T0':['LIB8','LIB9'],'vehicle':['LIB11','LIB12','LIB15'],'drug':['LIB10','LIB13','LIB14']}
for pseud in ['after_norm_each','after_norm_group_mean']:
 # Normalize by mapped depth.
 N=C.div(C.sum(axis=0),axis=1)
 if pseud=='after_norm_each':
  A=N+0.5/C.sum(axis=0)
 else:
  A=N.copy()
 def lfc(a,b):
  if pseud=='after_norm_each':
   x=np.log2(A[a].mean(axis=1)/A[b].mean(axis=1))
  else:
   x=np.log2((N[a].mean(axis=1)+0.5/C.sum(axis=0).mean())/(N[b].mean(axis=1)+0.5/C.sum(axis=0).mean()))
  return x-x.loc[nt].median()
 f=lfc(groups['vehicle'],groups['T0']); d=lfc(groups['drug'],groups['vehicle'])
 G=pd.DataFrame({'gene':lib.gene,'fitness':f,'drug':d}).groupby('gene').median()
 refs=pd.read_csv('/task/input/reference_genes.tsv',sep='\t').set_index('gene')
 print('\n',pseud)
 print('NTC medians after correction',f.loc[nt].median(),d.loc[nt].median())
 print(G.loc[refs.index].join(refs).to_string())
